$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$root=$PSScriptRoot
$repo=[IO.Path]::GetFullPath((Join-Path $root '../../..'))
$jobs=Get-Content -Encoding UTF8 -Raw (Join-Path $root 'inputs.json') | ConvertFrom-Json
function DataUri([string]$path) {'data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes($path))}
$entries=@()
foreach($j in $jobs){
    $current=$null
    if($j.current){$current=DataUri (Join-Path $repo $j.current)}
    $entries+=@{name=$j.name;label=$j.label;frames=$j.frames;pivot=@(128,$j.pivotY);width=256*$j.frames;height=$(if($j.frames -eq 1){128}else{256});current=$current;image=(DataUri (Join-Path $root ('sheets/'+$j.name+'.png')));motion=$j.motion;emissive=$j.emissive}
}
$json=ConvertTo-Json -Depth 6 -Compress -InputObject $entries
$hero=DataUri (Join-Path $repo 'Docs/References/codex_hero_octopath_review_v6/generated.png')
$context=DataUri (Join-Path $repo 'Docs/References/codex_k068_v1/input/03_pf_day_blast_clean.png')
$html=@'
<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K-072 · 전투 효과 6판</title>
<style>
:root{color-scheme:dark;font:16px/1.65 system-ui,sans-serif;background:#191b22;color:#eee8da}*{box-sizing:border-box}body{margin:0}main{max-width:1160px;margin:auto;padding:40px 24px}h1{font-size:36px;margin:0 0 12px}h2{font-size:23px;margin:0}p{color:#c4beb5}.eyebrow{color:#eac56b;letter-spacing:.12em}.intro{display:grid;grid-template-columns:1fr 150px;gap:32px}.hero{width:130px;height:195px;object-fit:contain;image-rendering:pixelated;background:#101115;border-radius:12px}.bar{position:sticky;top:0;z-index:2;background:#252731f5;padding:15px 24px;border-block:1px solid #49434a;display:flex;gap:20px;flex-wrap:wrap;align-items:center}button,select{font:inherit;padding:6px 14px;background:#3b3540;color:#fff1bf;border:1px solid #74645b;border-radius:6px}label{white-space:nowrap}section.effect{margin:32px 0;padding:24px;background:#23252e;border:1px solid #41424b;border-radius:12px}.meta{font-size:14px;color:#bcb2a6}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:18px}.pane{padding:16px;background:#181b21;border-radius:8px}.pane h3{margin:0 0 12px;font-size:15px;color:#eac56b}.stage{background:#52634d;display:flex;justify-content:center;min-height:256px;align-items:flex-end;border:1px solid #7a7b6a}.large{width:256px;height:256px;image-rendering:pixelated}.smallrow{display:flex;align-items:center;gap:20px;margin-top:16px;min-height:70px}.small{width:64px;height:64px;image-rendering:pixelated;background:#52634d}.smallrow span{font-size:13px;color:#bcb2a6}.sheet{max-width:100%;height:auto;image-rendering:pixelated;background:#34343e;display:block;margin-top:14px}details{margin-top:16px}summary{cursor:pointer;color:#d8c08b}.context{width:100%;border-radius:8px}.note{padding:14px 18px;border-left:3px solid #d8b96e;background:#28272c}a{color:#e8c36b}#health{font-size:14px;color:#d5bb7b}.empty{color:#bcb2a6;text-align:center;padding:80px 20px}@media(max-width:700px){.pair{grid-template-columns:1fr}.intro{grid-template-columns:1fr}.hero{display:none}main{padding:24px 12px}.bar{gap:10px;padding:12px}.effect{padding:16px!important}}
</style>
<main><div class="intro"><div><div class="eyebrow">HUMAN LAST RAMPART · K-072</div><h1>전투 효과 · 6판</h1><p>큰 도트 덩어리와 짙은 외곽선, 재질별 세 단계 명암을 기준으로 다시 그린 교체 후보입니다. 밝은 불꽃과 폭발은 금색·상아색 중심을 유지했습니다.</p><p class="note">왼쪽은 현재 게임 파일, 오른쪽은 새 시안입니다. 두 그림은 같은 셀 크기로 재생합니다. 아래 작은 그림은 64화소 셀에서의 판독성을 확인하는 축소 보기이며, 실제 게임 캡처는 아닙니다.</p></div><img class="hero" src="__HERO__" alt="사용자가 선택한 주인공 6판 처음 생성본"></div></main>
<div class="bar"><button id="pause">일시 정지</button><button id="step">한 칸 이동</button><label>속도 <select id="fps"><option value="6">초당 6칸</option><option value="10" selected>초당 10칸</option><option value="14">초당 14칸</option></select></label><label>배경 <select id="bg"><option value="#52634d">낮 들판</option><option value="#171a26">밤</option><option value="#b8b1a1">밝은 돌</option></select></label><label><input type="checkbox" id="pivot">기준점 표시</label><span id="health">이미지 확인 중…</span></div>
<main><p class="meta">투사체 3종 · 기존 효과 5종 · 공용 포구 연기 1종 · 신규 쓰러짐 먼지 1종. 고정 그림도 프레임 1칸으로 표시합니다. 반복 불꽃은 마지막 칸에서 첫 칸으로 연결되며, 폭발·불티·연기·먼지는 비교를 위해 반복 재생합니다.</p><div id="effects"></div><details><summary>오늘의 실제 전투 화면과 확인 범위</summary><p>아래는 제공받은 기존 전투 캡처입니다. 새 에셋을 연결한 결과가 아닙니다. 밝기 증폭·빛번짐·게임 안 표시 크기는 Claude 연결 후 실제 플레이에서 확인해야 합니다. 연기는 현재 포구 시트가 폭발 후 연기에도 재사용됩니다. 쓰러짐 먼지는 신규 연결이 필요합니다.</p><img class="context" src="__CONTEXT__" alt="기존 게임의 낮 전투와 폭발 캡처"></details><p class="meta">게임 파일은 변경하지 않았습니다. 이 페이지는 인터넷과 서버 없이 열 수 있도록 비교 이미지를 모두 내장했습니다.</p></main>
<script>
const assets=__DATA__;
const host=document.querySelector('#effects');const images=[];let tick=0,paused=false,last=0,acc=0,loaded=0,failed=0;
function img(src){const i=new Image();images.push(i);i.onload=()=>{loaded++;health()};i.onerror=()=>{failed++;health()};i.src=src;return i}
function health(){document.querySelector('#health').textContent=`비교 이미지 ${loaded}/${images.length}개 읽음${failed?' · 실패 '+failed+'개':''}`}
assets.forEach(a=>{const s=document.createElement('section');s.className='effect';s.innerHTML=`<h2>${a.label}</h2><div class="meta">${a.name}.png · ${a.width}×${a.height} · ${a.frames}칸 · 기준점 (${a.pivot.join(', ')}) · ${a.emissive?'발광 효과':'비발광'} · <span class="frame"></span></div><p>${a.motion}</p><div class="pair"></div><details><summary>새 시안 전체 시트 보기</summary><img class="sheet" alt="${a.label} 새 시안 전체 시트" src="${a.image}"></details>`;host.append(s);a.status=s.querySelector('.frame');a.views=[];for(const [label,source] of [['현재 게임',a.current],['새 시안',a.image]]){const p=document.createElement('div');p.className='pane';p.innerHTML=`<h3>${label}</h3>`;s.querySelector('.pair').append(p);if(!source){p.innerHTML+='<div class="empty">기존 시트 없음 · 신규 효과</div>';continue}const image=img(source);p.innerHTML+='<div class="stage"><canvas class="large" width="256" height="256"></canvas></div><div class="smallrow"><canvas class="small" width="64" height="64"></canvas><span>64화소 셀 축소 보기<br>최근접 보간 · 외곽선 확인</span></div>';a.views.push({image,large:p.querySelector('.large'),small:p.querySelector('.small')})}});
function draw(){const bg=document.querySelector('#bg').value;for(const a of assets){const f=tick%a.frames;a.status.textContent=`${f+1}/${a.frames}칸`;for(const v of a.views){for(const c of [v.large,v.small]){const g=c.getContext('2d');g.imageSmoothingEnabled=false;g.fillStyle=bg;g.fillRect(0,0,c.width,c.height);const scale=c.width/256;const y=(256-a.height)/2;if(v.image.complete&&v.image.naturalWidth)g.drawImage(v.image,f*256,0,256,a.height,0,y*scale,c.width,a.height*scale);if(document.querySelector('#pivot').checked){const px=a.pivot[0]*scale,py=Math.min(c.height-1,(y+a.pivot[1])*scale);g.strokeStyle='#5effce';g.lineWidth=1;g.beginPath();g.moveTo(0,py+.5);g.lineTo(c.width,py+.5);g.moveTo(px+.5,py-7);g.lineTo(px+.5,Math.min(c.height,py+7));g.stroke()}}}}}
function loop(t){const dt=Math.min(t-last,200);last=t;if(!paused){acc+=dt;const frameMs=1000/Number(document.querySelector('#fps').value);while(acc>=frameMs){tick++;acc-=frameMs}}draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelector('#pause').textContent=paused?'재생':'일시 정지'};document.querySelector('#step').onclick=()=>{paused=true;document.querySelector('#pause').textContent='재생';tick++;draw()};document.querySelector('#bg').onchange=()=>{document.querySelectorAll('.stage,.small').forEach(e=>e.style.background=document.querySelector('#bg').value)};
</script></html>
'@
$html=$html.Replace('__DATA__',$json).Replace('__HERO__',$hero).Replace('__CONTEXT__',$context)
$dest=Join-Path $repo '_HTML/5_그림_전장/codex_K-072_효과6판_v1.html'
[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($dest)) | Out-Null
[IO.File]::WriteAllText($dest,$html,(New-Object Text.UTF8Encoding $false))
Write-Output $dest
